{
  "id": "openclaw-code-agent",
  "name": "Code Agent",
  "description": "Multi-session coding-agent orchestration from OpenClaw chat",
  "version": "6.0.4",
  "contracts": {
    "tools": [
      "agent_launch",
      "agent_sessions",
      "agent_kill",
      "agent_output",
      "agent_respond",
      "agent_session_action",
      "agent_escalate",
      "agent_send_plan_offer",
      "agent_stats",
      "agent_repo_policy",
      "agent_merge",
      "agent_pr",
      "agent_worktree_cleanup",
      "agent_worktree_status",
      "agent_goal"
    ]
  },
  "configContracts": {
    "dangerousFlags": [
      {
        "path": "permissionMode",
        "equals": "bypassPermissions"
      },
      {
        "path": "planApproval",
        "equals": "approve"
      },
      {
        "path": "defaultWorktreeStrategy",
        "equals": "auto-merge"
      },
      {
        "path": "defaultWorktreeStrategy",
        "equals": "auto-pr"
      },
      {
        "path": "harnesses.codex.permissionProfile",
        "equals": ":danger-full-access"
      },
      {
        "path": "harnesses.codex.approvalPolicy",
        "equals": "never"
      }
    ]
  },
  "activation": {
    "onStartup": true,
    "onCommands": [
      "agent",
      "agent_kill",
      "agent_output",
      "agent_respond",
      "agent_sessions",
      "agent_stats",
      "agent_policy",
      "agent_status",
      "agent_goal"
    ]
  },
  "setup": {
    "requiresRuntime": false
  },
  "configSchema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "maxSessions": {
        "type": "number",
        "default": 20,
        "description": "Maximum concurrently active sessions; further launches are refused."
      },
      "harnesses": {
        "type": "object",
        "description": "Per-harness launch defaults and model restrictions.",
        "default": {
          "codex": {
            "defaultModel": "gpt-6.1-sol",
            "allowedModels": [
              "gpt-6.1-sol",
              "gpt-6-sol",
              "gpt-6-astra",
              "gpt-6-luna",
              "gpt-5.6-sol",
              "gpt-5.6-terra",
              "gpt-5.6-luna"
            ],
            "reasoningEffort": "medium",
            "fastMode": false
          },
          "claude-code": {
            "defaultModel": "opus",
            "allowedModels": [
              "sonnet",
              "opus"
            ]
          },
          "opencode": {}
        },
        "additionalProperties": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "defaultModel": {
              "type": "string",
              "description": "Default model for this harness when agent_launch omits model. For OpenCode, omit this to use OpenCode's configured provider default."
            },
            "allowedModels": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Models this harness may launch. When omitted, Codex and Claude Code keep their built-in allowlist, unless this entry also sets defaultModel, which clears it. An empty array means no restriction."
            },
            "reasoningEffort": {
              "type": "string",
              "enum": [
                "low",
                "medium",
                "high",
                "xhigh",
                "max"
              ],
              "description": "Harness-specific reasoning effort. Passed to Codex (as the turn effort, skipped when Codex's model/list says the model does not support it), to Claude Code as its effort, and to OpenCode as the prompt variant. Codex defaults to medium; explicit values override it."
            },
            "fastMode": {
              "type": "boolean",
              "default": false,
              "description": "Codex-only fast mode. When true under harnesses.codex, Codex App Server threads request serviceTier=\"priority\" (Codex's fast tier); API-key cost estimates apply the fast multiplier only when Codex reports the priority tier as active."
            },
            "permissionProfile": {
              "type": "string",
              "enum": [
                ":read-only",
                ":workspace",
                ":danger-full-access"
              ],
              "description": "Codex-only built-in permission profile sent as the thread `permissions`. Unset follows the host tools.exec.mode like OpenClaw's bundled Codex plugin: ':workspace' for 'auto' and 'ask', ':danger-full-access' when tools.exec.mode is 'full' or unset; 'deny' and 'allowlist' block Codex unless this is set. ':workspace' allows writes inside the workspace with network off; ':read-only' blocks writes; ':danger-full-access' disables the sandbox. An explicit value always wins over tools.exec.mode."
            },
            "approvalPolicy": {
              "type": "string",
              "enum": [
                "never",
                "on-request",
                "untrusted"
              ],
              "description": "Codex-only approval policy. Unset follows the host tools.exec.mode: 'on-request' for 'auto' and 'ask', 'never' when tools.exec.mode is 'full' or unset. 'on-request' asks before escalating out of the sandbox (for example network access or writes outside the workspace); the request goes to approvalsReviewer. 'untrusted' also asks before commands Codex does not consider safe. 'never' never asks."
            },
            "approvalsReviewer": {
              "type": "string",
              "enum": [
                "user",
                "auto_review"
              ],
              "description": "Codex-only reviewer for approval requests: 'user' (requests are sent to the chat as approval buttons) or 'auto_review' (opt-in; Codex's reviewer subagent approves or denies each request based on the task and its risk). Unset follows the host tools.exec.mode: 'auto_review' for 'auto', 'user' otherwise."
            },
            "command": {
              "type": "string",
              "minLength": 1
            },
            "passEnv": {
              "type": "array",
              "items": {
                "type": "string",
                "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
              },
              "uniqueItems": true
            },
            "defaultAgent": {
              "type": "string",
              "minLength": 1
            },
            "serverMode": {
              "type": "string",
              "enum": [
                "private"
              ]
            }
          }
        }
      },
      "defaultWorkdir": {
        "type": "string",
        "description": "Default working directory for new sessions. Because the default worktree strategy is 'delegate', this should normally be a git repository root unless defaultWorktreeStrategy is changed to 'off'."
      },
      "idleTimeoutMinutes": {
        "type": "number",
        "default": 15,
        "description": "Minutes a multi-turn session may sit idle before OCA suspends it (stops the backend process; the session stays resumable with agent_respond or the Resume button)."
      },
      "sessionGcAgeMinutes": {
        "type": "number",
        "default": 1440,
        "description": "TTL in minutes before terminal runtime sessions are evicted from memory (persisted metadata remains resumable)."
      },
      "maxPersistedSessions": {
        "type": "number",
        "default": 10000,
        "description": "Maximum number of persisted session records kept in the session index for resume and history. Beyond this, the oldest by completion time are removed. sessionGcAgeMinutes only controls eviction of terminal sessions from memory."
      },
      "fallbackChannel": {
        "type": "string",
        "description": "Fallback notification channel. Prefer a fully routable value such as 'telegram|123456789' or 'telegram|my-bot|123456789'; a bare provider like 'telegram' is only a weak fallback."
      },
      "permissionMode": {
        "type": "string",
        "default": "plan",
        "enum": [
          "default",
          "plan",
          "bypassPermissions"
        ],
        "description": "Default plugin orchestration mode for coding-agent sessions. This controls OpenClaw plan/default/bypass behavior. The Codex sandbox and approval prompts are configured separately with harnesses.codex.permissionProfile, approvalPolicy, and approvalsReviewer."
      },
      "agentChannels": {
        "type": "object",
        "description": "Map of agent working directories to notification channels",
        "additionalProperties": {
          "type": "string"
        }
      },
      "maxAutoResponds": {
        "type": "number",
        "default": 10,
        "description": "Maximum consecutive auto-responds per session before requiring user input"
      },
      "planApproval": {
        "type": "string",
        "default": "delegate",
        "enum": [
          "approve",
          "ask",
          "delegate"
        ],
        "description": "Plan approval behavior. 'delegate' (default): orchestrator must review the full plan, then approve low-risk plans or escalate to the user. 'ask': always forwards plans to the user for approval. 'approve': orchestrator may approve without asking the user, but only after verifying the full plan; destructive or out-of-scope plans still go to the user."
      },
      "defaultHarness": {
        "type": "string",
        "enum": ["claude-code", "codex", "opencode"],
        "default": "claude-code",
        "description": "Default agent harness when agent_launch omits the harness parameter. Choose Claude Code, Codex, or OpenCode."
      },
      "defaultWorktreeStrategy": {
        "type": "string",
        "default": "delegate",
        "enum": ["off", "manual", "ask", "delegate", "auto-merge", "auto-pr"],
        "description": "Default worktree strategy for all new sessions when agent_launch omits worktree_strategy. Repo integration policy still governs whether merge or PR follow-through is allowed. 'delegate' (default) creates an isolated worktree and wakes the orchestrator to decide follow-through autonomously. 'off' = no worktree. 'manual' = create worktree, no automatic action; the worktree is kept after the session ends. 'ask' = notify the user with state-aware buttons such as Merge, Open PR, View PR, Sync PR, Later, and Discard when policy allows them. 'auto-merge' = request automatic merge to base branch on completion. 'auto-pr' = request automatic GitHub PR creation/update on completion."
      },
      "worktreeDir": {
        "type": "string",
        "description": "Base directory for agent worktrees. Defaults to <repoRoot>/.worktrees when unset. Overridden by OPENCLAW_WORKTREE_DIR env var."
      },
      "worktreeGitHooks": {
        "type": "string",
        "default": "run",
        "enum": ["run", "skip"],
        "description": "Repository git hooks during OCA's own git operations (merge, rebase, squash commit, push, and worktree creation). 'run' (default) runs them as git normally would; 'skip' runs those commands with core.hooksPath=/dev/null. Either way, a merge or PR whose branch changes hook locations (.husky/, .githooks/, the core.hooksPath directory, .openclaw/worktree-setup.sh, .worktreeinclude) is never automatic: the user is asked with a button that names the changed files."
      },
      "trustedVerifierCommands": {
        "type": "array",
        "items": { "type": "string" },
        "description": "Additional goal verifier commands the operator pre-approves (exact strings). Required policy checks are already approved. Model-supplied additions all in this list skip the one-time user confirmation; any other model-supplied addition needs confirmation first."
      },
      "planOfferTool": {
        "type": "boolean",
        "default": false,
        "description": "Register the agent_send_plan_offer tool, which posts a message with Start plan / Dismiss buttons for external workflows. Off by default so orchestrators do not see it."
      },
      "autoUpdate": {
        "type": "boolean",
        "default": true,
        "description": "Check daily for a newer OpenClaw Code Agent release and offer it with Update now / Remind later / Skip this version buttons. The plugin reinstalls itself (openclaw plugins install <exact version> --force) only after a user presses Update now, and restarts the Gateway (openclaw gateway restart) only after a separate Restart Gateway press. false disables update checks, installs, and restarts entirely."
      },
      "requiredGoalVerifierCommands": {
        "description": "Removed configuration. Migrate to goalVerificationPolicies.repositories with requiredCommands or an explicit defaultRequiredCommands, then start new goals. This legacy field denies goal work; historical evidence is preserved."
      },
      "goalVerificationPolicies": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "repositories": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "repository",
                "requiredCommands"
              ],
              "properties": {
                "repository": {
                  "type": "string",
                  "minLength": 1,
                  "description": "Operator-owned absolute path inside the actual Git repository. Linked worktrees and symlinks share its canonical Git common-directory identity; duplicate identities are invalid."
                },
                "requiredCommands": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "\\S"
                  }
                }
              }
            }
          },
          "defaultRequiredCommands": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string",
              "minLength": 1,
              "pattern": "\\S"
            }
          }
        },
        "anyOf": [
          {
            "required": [
              "repositories"
            ]
          },
          {
            "required": [
              "defaultRequiredCommands"
            ]
          }
        ],
        "description": "Operator-owned complete required checks per actual repository. Goal verifier_commands are additional checks appended in order, retaining duplicates. Configured unmatched repositories and nonrepositories require an explicit default; invalid identities/configuration deny goal work. Absent configuration preserves caller-verifier behavior."
      }
    }
  },
  "uiHints": {
    "fallbackChannel": {
      "label": "Fallback notification channel",
      "help": "Optional but recommended. Default channel used when no workspace-specific agentChannels entry matches the session workdir. Also used for plugin update prompts. Prefer a fully routable channel string; bare providers are only weak fallbacks.",
      "placeholder": "telegram|my-bot|123456789"
    },
    "agentChannels": {
      "label": "Workspace notification channels",
      "help": "Map absolute working-directory paths to notification channels so each workspace routes session updates to the right chat.",
      "sensitive": true,
      "advanced": true
    },
    "defaultWorkdir": {
      "label": "Default working directory",
      "help": "Base directory used for new sessions when agent_launch does not provide a workdir. With the default delegated worktree strategy, choose a git repository root; use the advanced worktree strategy setting to disable worktrees for non-git directories.",
      "placeholder": "/home/user/project"
    },
    "harnesses": {
      "label": "Harness configuration",
      "help": "Per-harness defaults and model restrictions. Set harnesses.codex.fastMode=true to request Codex's priority (fast) service tier. harnesses.codex.permissionProfile / approvalPolicy / approvalsReviewer control the Codex sandbox and approval prompts; when unset they follow the host tools.exec.mode like OpenClaw's bundled Codex plugin ('full' or unset: full access, no prompts; 'auto': ':workspace' + 'on-request' + 'auto_review'; 'ask': the same with approvals in chat), and explicit values always win. Leave harnesses.opencode.defaultModel unset to use OpenCode's provider default, or pass provider/model explicitly. Default: {\"codex\":{\"defaultModel\":\"gpt-6.1-sol\",\"allowedModels\":[\"gpt-6.1-sol\",\"gpt-6-sol\",\"gpt-6-astra\",\"gpt-6-luna\",\"gpt-5.6-sol\",\"gpt-5.6-terra\",\"gpt-5.6-luna\"],\"reasoningEffort\":\"medium\",\"fastMode\":false},\"claude-code\":{\"defaultModel\":\"opus\",\"allowedModels\":[\"sonnet\",\"opus\"]},\"opencode\":{}}.",
      "advanced": true
    },
    "maxSessions": {
      "label": "Maximum concurrent sessions",
      "help": "Upper limit on concurrently running coding-agent sessions.",
      "advanced": true
    },
    "idleTimeoutMinutes": {
      "label": "Idle timeout (minutes)",
      "help": "Minutes a session waiting for input can stay idle before the plugin suspends it. A suspended session keeps its conversation and resumes on the next agent_respond.",
      "advanced": true
    },
    "defaultHarness": {
      "label": "Default harness",
      "help": "Choose the harness you expect to use most often. Pick Codex only when the Codex command and local auth are ready on this machine. Pick OpenCode when local opencode >= 2.0.25 (@opencode/cli) and provider auth are ready.",
      "placeholder": "claude-code"
    },
    "permissionMode": {
      "label": "Default permission mode",
      "help": "Default plugin orchestration mode used when new coding-agent sessions are launched. Use this for plan/default/bypass behavior; the Codex sandbox and approval prompts come from harnesses.codex.permissionProfile, approvalPolicy, and approvalsReviewer.",
      "advanced": true
    },
    "planApproval": {
      "label": "Plan approval policy",
      "help": "Choose whether plans are delegated to the orchestrator for full-plan review first (`delegate`, default), always sent to the user with Approve/Revise/Reject buttons, or approved by the orchestrator after it verifies the plan (`approve`).",
      "advanced": true
    },
    "autoUpdate": {
      "label": "Plugin self-update",
      "help": "On (default): check daily for a newer release and offer it with buttons. Installing and restarting the Gateway each need an explicit button press. Off: no update checks, installs, or restarts.",
      "advanced": true
    },
    "worktreeGitHooks": {
      "label": "Repository git hooks in OCA git operations",
      "help": "'run' (default) or 'skip' repository hooks (for example husky) when OCA merges, rebases, commits, pushes, or creates worktrees. Merges and PRs that change hook files always ask the user first.",
      "advanced": true
    },
    "planOfferTool": {
      "label": "Plan offer tool",
      "help": "Register agent_send_plan_offer for external workflows that offer a plan-only session with Start plan / Dismiss buttons.",
      "advanced": true
    },
    "trustedVerifierCommands": {
      "label": "Pre-approved goal verifier commands",
      "help": "Exact shell commands goal loops may run as verifiers without asking the user. Other commands suggested by the orchestrator need one confirmation button at goal launch.",
      "advanced": true
    },
    "worktreeDir": {
      "label": "Worktree directory",
      "help": "Base directory for OCA worktrees; defaults to <repoRoot>/.worktrees. OPENCLAW_WORKTREE_DIR takes precedence.",
      "advanced": true
    },
    "maxAutoResponds": {
      "label": "Maximum auto-responds",
      "help": "Consecutive orchestrator auto-responds allowed per session before user input is required.",
      "advanced": true
    },
    "sessionGcAgeMinutes": {
      "label": "Session memory TTL (minutes)",
      "help": "Minutes before finished sessions are evicted from memory. Persisted sessions stay resumable.",
      "advanced": true
    },
    "maxPersistedSessions": {
      "label": "Maximum persisted sessions",
      "help": "Maximum session records kept in the session index; the oldest finished sessions are removed first.",
      "advanced": true
    },
    "defaultWorktreeStrategy": {
      "label": "Default worktree strategy",
      "help": "Applies to all sessions that don't specify worktree_strategy explicitly. Repo policy can downgrade unsafe or impossible merge/PR follow-through. 'delegate' (default) creates a worktree and wakes the orchestrator to decide follow-through. 'off' disables worktrees for sessions that don't request one. 'manual' creates a worktree and keeps it for explicit follow-through. 'ask' sends state-aware inline worktree buttons such as Merge, Open PR, View PR, Sync PR, Later, and Discard when policy allows them.",
      "advanced": true
    },
    "requiredGoalVerifierCommands": {
      "label": "Removed global goal verifiers",
      "help": "Migration required: replace with goalVerificationPolicies, then start new goals. Existing terminal evidence is preserved.",
      "advanced": true
    },
    "goalVerificationPolicies": {
      "label": "Repository goal verification policies",
      "help": "Operator-owned repository paths and complete required suites, with optional explicit defaultRequiredCommands. Goal checks append to the baseline. Linked worktrees share repository identity. Active goals are invalidated only when their selected policy or identity changes.",
      "advanced": true
    },
    "harnesses.opencode.command": {
      "label": "OpenCode command"
    },
    "harnesses.opencode.passEnv": {
      "label": "OpenCode environment allowlist"
    },
    "harnesses.opencode.defaultAgent": {
      "label": "OpenCode build agent"
    },
    "harnesses.opencode.serverMode": {
      "label": "OpenCode server mode"
    }
  },
  "skills": [
    "./skills"
  ]
}
